import java.io.*;

public class Main {
    static void a() throws IOException {
        throw new IOException("io");
    }
    static void b() {
        throw new AssertionError("err");
    }
    static void run() throws IOException {
        try {
            b();
        } catch (Error e) {
            System.out.print("E ");
        }
        a();
        System.out.print("X");
    }
    public static void main(String[] args) {
        try {
            run();
        } catch (Exception e) {
            System.out.print("IO " + e.getMessage());
        }
    }
}

