public class Main {
    public static void main(String[] args) {
        try {
            try {
                Object s = "x";
                Integer i = (Integer) s;
                System.out.print("1");
            } catch (ClassCastException e) {
                System.out.print("2");
                throw new IllegalStateException("bad");
            } catch (IllegalStateException e) {
                System.out.print("3");
            } catch (RuntimeException e) {
                System.out.print("4");
            } finally {
                System.out.print("5");
            }
            System.out.print("6");
        } catch (Exception e) {
            System.out.print("7");
        }
    }
}

