// Box and Other are in the SAME package
class Box {
    private   int a = 1;
    int           b = 2;   // package-private
    protected int c = 3;
    public    int d = 4;
}
class Other {               // NOT a subclass of Box
    void test(Box x) {
        System.out.print(x.a);   // L1
        System.out.print(x.b);   // L2
        System.out.print(x.c);   // L3
        System.out.print(x.d);   // L4
    }
}

